def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def read(path):
 def pairs(rows):
  out={}
  for k,v in rows:
   require(k not in out,'Duplicate JSON key');out[k]=v
  return out
 def reject(value):raise ValueError('Nonfinite JSON constant '+value)
 def check(x):
